   121	 * @returns Decoded text truncated at the cap, or null when the stream fails mid-read.
   122	 */
   123	async function readCapped(res: Response): Promise<string | null> {
   124		const reader = res.body?.getReader();
   125		if (!reader) return '';
   126		const chunks: Uint8Array[] = [];
   127		let size = 0;
   128		try {
   129			while (size < MAX_BYTES) {
   130				const { done, value } = await reader.read();
   131				if (done) break;
   132				chunks.push(value);
   133				size += value.length;
   134			}
   135		} catch {
   136			return null;
   137		} finally {
   138			await reader.cancel().catch(() => undefined);
   139		}
   140		return Buffer.concat(chunks).subarray(0, MAX_BYTES).toString('utf8');
   141	}
