   144	 * Builds a per-call robots gate that fetches each origin's robots.txt at most once.
   145	 * @returns A hop check: true when that origin's robots.txt permits Gravespeaker to fetch the URL.
   146	 */
   147	function robotsGate(): (url: URL) => Promise<boolean> {
   148		const cache = new Map<string, Promise<(href: string) => boolean>>();
   149		/**
   150		 * Loads one origin's robots.txt and returns its verdict function.
   151		 * @param origin Origin to load robots.txt from.
   152		 * @returns A permission check. A 4xx robots.txt means no rules (allow all). Per RFC 9309 an
   153		 * unreachable, 5xx, unfollowed 3xx or unreadable one means disallow all.
   154		 */
   155		const load = async (origin: string): Promise<(href: string) => boolean> => {
   156			const res = await guardedFetch(`${origin}/robots.txt`);
   157			if (!res) return () => false;
   158			if (res.status >= 400 && res.status < 500) return () => true;
   159			if (!res.ok) return () => false;
