   177	 * @param url Source URL from a search record.
   178	 * @returns Readable text, or null when blocked, disallowed, gated, non-HTML, unreadable or empty.
   179	 */
   180	export async function fetchPage(url: string): Promise<string | null> {
   181		const res = await guardedFetch(url, robotsGate());
   182		if (!res?.ok || !res.headers.get('content-type')?.includes('html')) return null;
