   184		if (body === null) return null;
   185		const { document } = parseHTML(body);
   186		// Readability skips inline-hidden nodes but not CSS-hidden ones. Find a Grave ships a hidden
   187		// welcome tour that it would otherwise take as the article instead of the memorial.
   188		for (const el of document.querySelectorAll(HIDDEN)) el.remove();
