   190		try {
   191			text = new Readability(document as unknown as Document).parse()?.textContent;
   192		} catch {
   193			// Readability throws on documents linkedom builds without an <html> root, such as bot walls.
   194			return null;
   195		}
   196		return text?.replace(/\s+/g, ' ').trim() || null;
