  8	import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
  9	import { afterAll, describe, expect, it, vi } from 'vitest';
 10	import { normalizeInscriptions } from '../src/lib/server/inscription.ts';
