 20	const { env } = vi.hoisted(() => {
 21		process.loadEnvFile('.env');
 22		return { env: { SERPAPI_API_KEY: process.env.SERPAPI_API_KEY } };
 23	});
 24	vi.mock('$app/env/private', () => env);
 25	
 26	const SAVED = 'fixtures/serp';
 27	const RECORD = process.env.RECORD === '1';
 28	const WITH_PLACE = process.env.NO_PLACE !== '1';
 29	const live = globalThis.fetch;
 30	// Searches each person's run made, and searches with no saved response in replay mode.
 31	let ran: string[] = [];
 32	const missing = new Set<string>();
 33	let recorded = 0;
 34	
 35	/**
 36	 * Removes the API key from a SerpApi response before it is saved.
 37	 * @param value Parsed response, or part of one.
 38	 * @returns The value without any `api_key` field.
 39	 */
 40	function scrub(value: unknown): unknown {
 41		if (Array.isArray(value)) return value.map(scrub);
 42		if (!value || typeof value !== 'object') return value;
 43		return Object.fromEntries(
 44			Object.entries(value)
 45				.filter(([k]) => k !== 'api_key')
 46				.map(([k, v]) => [k, scrub(v)])
 47		);
 48	}
 49	
 50	/**
 51	 * Answers a Google redirect hop from its saved location, recording it when RECORD=1.
 52	 * @param url Redirect URL.
 53	 * @param init Request options.
 54	 * @returns The saved or live redirect.
 55	 */
 56	async function hop(url: URL, init?: RequestInit): Promise<Response> {
 57		const id = createHash('sha256').update(url.href).digest('hex').slice(0, 16);
 58		const file = `${SAVED}/goto-${id}.json`;
 59		if (!existsSync(file) && !RECORD) {
 60			missing.add(`goto: ${url.href}`);
 61			return new Response(null, { status: 599 });
 62		}
 63		if (!existsSync(file)) {
 64			const res = await live(url, init);
 65			const saved = { url: url.href, status: res.status, location: res.headers.get('location') };
 66			writeFileSync(file, `${JSON.stringify(saved, null, '\t')}\n`);
 67			recorded++;
 68		}
 69		const { status, location } = JSON.parse(readFileSync(file, 'utf8'));
 70		return new Response(null, { status, headers: location ? { location } : {} });
 71	}
 72	
 73	/**
 74	 * Answers SerpApi requests from saved responses, recording new ones when RECORD=1.
 75	 * @param input Request URL.
 76	 * @param init Request options.
 77	 * @returns The saved or live response.
 78	 */
 79	async function replay(input: string | URL | Request, init?: RequestInit): Promise<Response> {
 80		const url = new URL(input instanceof Request ? input.url : String(input));
 81		if (url.host === 'www.google.com') return hop(url, init);
 82		if (url.host !== 'serpapi.com') return live(input, init);
 83		url.searchParams.delete('api_key');
 84		url.searchParams.sort();
 85		const engine = url.searchParams.get('engine');
 86		const query = url.searchParams.get('q') ?? url.searchParams.get('text');
 87		ran.push(`${engine}: ${query}`);
 88		const id = createHash('sha256').update(url.search).digest('hex').slice(0, 16);
 89		const file = `${SAVED}/${engine}-${id}.json`;
 90		if (existsSync(file)) {
 91			const saved = JSON.parse(readFileSync(file, 'utf8'));
 92			return Response.json(saved.body, { status: saved.status });
 93		}
 94		if (!RECORD) {
 95			missing.add(`${engine}: ${query}`);
 96			return Response.json({ error: 'not recorded' }, { status: 599 });
 97		}
 98		let status: number;
 99		let body: unknown;
100		try {
101			const res = await live(input, init);
102			status = res.status;
103			body = scrub(await res.json());
104		} catch (e) {
105			// A search SerpApi never answers is saved too, so a replay takes the same fallback path.
106			status = 504;
107			body = { error: `Not answered while recording: ${(e as Error).name}` };
108		}
109		const text = JSON.stringify({ engine, query, status, body }, null, '\t');
110		// A saved response must never carry the key, whatever SerpApi echoes back.
111		if (env.SERPAPI_API_KEY && text.includes(env.SERPAPI_API_KEY)) throw new Error('key in response');
112		mkdirSync(SAVED, { recursive: true });
113		writeFileSync(file, `${text}\n`);
114		recorded++;
115		return Response.json(body, { status });
116	}
117	vi.stubGlobal('fetch', replay);
118	
119	/**
120	 * Reads a fixture file.
121	 * @param path File relative to the repo root.
122	 * @returns Its fixtures.
123	 */
124	const load = (path: string) => JSON.parse(readFileSync(path, 'utf8')) as Fixture[];
125	// Photo fixtures count once reviewed; people.json cases carry no photo and are labeled per row.
126	// FIXTURES=people runs only the people.json cases, whose own memorial is known.
127	const fixtures = [
128		...(process.env.FIXTURES === 'people'
129			? []
130			: load('fixtures/manifest.json').filter((f) => f.reviewed)),
131		...load('fixtures/people.json')
132	];
133	/**
134	 * Names a labeled place the way the app's geocoder does: town and state, the county only when no town
135	 * is known.
136	 * @param place Label such as "Eugene, Lane County, Oregon".
137	 * @returns The place as research receives it, such as "Eugene, Oregon".
138	 */
139	function asGeocoded(place: string | null): string | null {
140		const parts = place?.split(', ') ?? [];
141		return parts.length === 3 ? `${parts[0]}, ${parts[2]}` : (place ?? null);
142	}
143	
144	const rows: unknown[] = [];
145	
146	describe('research', () => {
147		it.each(fixtures.flatMap((f) => f.people.map((p) => [`${f.file} ${p.name}`, f, p] as const)))(
148			'%s',
149			async (_, fixture, person) => {
150				ran = [];
151				// Normalized as the app does. The voice stays empty so the story eval checks the voice the
152				// records give, not the label.
153				const [inscription] = normalizeInscriptions([
154					{ ...person, voice: null, place: WITH_PLACE ? asGeocoded(fixture.place) : null }
155				]);
156				const candidates = await runResearch(inscription);
157				rows.push({
158					file: fixture.file,
159					reviewed: fixture.reviewed,
160					person,
161					inscription,
162					searches: ran,
163					candidates
164				});
165				expect(candidates).toBeInstanceOf(Array);
166			},
167			// Up to six live searches run one after another while recording.
168			120_000
169		);
170	});
171	
172	afterAll(() => {
173		const runs = readdirSync('benchmarks/results')
174			.map((f) => /^research-(\d+)\.json$/.exec(f)?.[1])
175			.filter(Boolean)
176			.map(Number);
177		const out = `benchmarks/results/research-${Math.max(0, ...runs) + 1}.json`;
178		const meta = {
179			startedAt: new Date().toISOString(),
180			withPlace: WITH_PLACE,
181			recorded,
182			missing: [...missing]
183		};
184		writeFileSync(out, `${JSON.stringify({ meta, rows }, null, '\t')}\n`);
185		console.log(
186			`${out}: ${rows.length} people, ${recorded} searches recorded, ${missing.size} missing`
187		);
