  3	// - stories-written.json: hand-written records that bait specific failures, always the right person.
  4	// - stories-recorded.json: real search results, which may describe someone else until labeled.
  5	import { afterAll, describe, expect, it, vi } from 'vitest';
  6	import { epitaph } from '../../src/lib/epitaph.ts';
  7	import { runStoneStory, runStory } from '../../src/lib/server/story.ts';
  8	import type { Candidate, Inscription, Voice } from '../../src/lib/types.ts';
  9	import { lifeClaimsScorer } from './life-claims.ts';
 10	import { ageAtDeath, yearsOutsideLife } from './stone-years.ts';
 11	
 12	interface StoryCase {
 13		inscription: Inscription;
 14		candidates: Candidate[];
 15		pages: Record<string, string | null>;
 16		match: number | null;
 17		reviewed: boolean;
 18		/** The narrator the person should get, whatever the name suggests. */
 19		voice: Voice;
 20		/** Hand-written stories that check the graders: `good` must pass, `bad` must fail. */
 21		good?: string;
 22		bad?: string;
 23	}
 24	
 25	// Hoisted above the imports, so node:fs is reached without one.
 26	const { sets, env } = vi.hoisted(() => {
 27		const { readFileSync } = process.getBuiltinModule('node:fs');
 28		process.loadEnvFile('.env');
 29		/**
 30		 * Reads one fixture set.
 31		 * @param path Fixture file, relative to the repo root.
 32		 * @returns Its cases.
 33		 */
 34		const load = (path: string) => JSON.parse(readFileSync(path, 'utf8')) as StoryCase[];
 35		return {
 36			sets: {
 37				written: load('fixtures/stories-written.json'),
 38				recorded: load('fixtures/stories-recorded.json')
 39			},
 40			env: { GEMINI_API_KEY: process.env.GEMINI_API_KEY }
 41		};
 42	});
 43	vi.mock('$app/env/private', () => env);
 44	vi.mock('../../src/lib/server/pages.ts', () => ({
 45		fetchPage: async (url: string) =>
 46			[...sets.written, ...sets.recorded].find((c) => url in c.pages)?.pages[url] ?? null
 47	}));
 48	
 49	const scorer = lifeClaimsScorer(env.GEMINI_API_KEY ?? '');
 50	const timings: number[] = [];
 51	// Trial outcomes per set and person, for pass@1 (share of trials) and pass^3 (every trial).
 52	const trials = new Map<string, Map<string, boolean[]>>();
 53	// Narrator picks per set, kept apart from story trials so a wrong voice does not hide in them.
 54	const voices = new Map<string, boolean[]>();
 55	// The story model samples at temperature 1, so one passing draw proves little. A case passes only
 56	// when every draw does.
 57	const SAMPLES = 3;
 58	
 59	/**
 60	 * Picks the candidate the story is told about: the labeled match, else the top hit.
 61	 * @param c Recorded case.
 62	 * @returns The candidate, or undefined when research found none or none is the person.
 63	 */
 64	function told(c: StoryCase): Candidate | undefined {
 65		return c.match === -1 ? undefined : c.candidates[c.match ?? 0];
 66	}
 67	
 68	/**
 69	 * Runs both graders on one paragraph.
 70	 * @param c The case.
 71	 * @param paragraph The story to grade.
 72	 * @param fromRecords Whether the story was told from the candidate's records or the stone alone.
 73	 * @returns Years outside the stone's life, the judge's score, and its reasons.
 74	 */
 75	async function grade(
 76		c: StoryCase,
 77		paragraph: string,
 78		fromRecords: boolean
 79	): Promise<{ years: number[]; score: number; reason: string }> {
 80		const age = ageAtDeath(c.inscription);
 81		const stone = [...epitaph(c.inscription, new Date()), ...(age ? [age] : [])];
 82		// Every source of the candidate counts, not just those cited: a true claim is never a failure.
 83		const records = fromRecords ? told(c)!.sources.map((s) => c.pages[s.url] ?? s.snippet) : [];
 84		const result = await scorer.run({
 85			input: { subject: c.inscription.name, context: [...stone, ...records] },
 86			output: paragraph
 87		});
 88		return {
 89			years: yearsOutsideLife(paragraph, c.inscription),
 90			// A run the scorer could not score counts as a failure.
 91			score: result.score ?? 0,
 92			reason: result.reason ?? ''
 93		};
 94	}
