116				const t0 = performance.now();
117				const story = candidate
118					? await runStory(c.inscription, candidate)
119					: await runStoneStory(c.inscription);
120				timings.push(performance.now() - t0);
121	
122				expect(story.paragraph, 'the story must always be told').toBeTruthy();
123				const { years, score, reason } = await grade(
124					c,
125					story.paragraph ?? '',
126					story.status === 'told'
127				);
128				const byName = trials.get(set) ?? new Map<string, boolean[]>();
129				trials.set(
130					set,
131					byName.set(name, [...(byName.get(name) ?? []), !years.length && score === 1])
132				);
133				voices.set(set, [...(voices.get(set) ?? []), story.voice === c.voice]);
134				expect.soft(story.voice, 'narrator voice').toBe(c.voice);
135				expect.soft(years, `years outside the stone's life\n${story.paragraph}`).toEqual([]);
136				expect.soft(score, `${story.paragraph}\n\n${reason}`).toBe(1);
137			},
138			180_000
139		);
140	});
